Un árbol genealógico guarda, para cada persona, una lista con sus hijos; cada hijo puede tener más hijos. Se quiere contar cuántos hay en total.

function contarPersonas(familia) {
  let total = 0;
  for (const hijo of familia) {
    total += 1 + contarPersonas(hijo);
  }
  return total;
}
